const raw = String($input.first().json.text || '').replace(/```(?:json)?/gi, '').trim();
let data;
try {
  const start = raw.indexOf('['), end = raw.lastIndexOf(']');
  if (start < 0 || end < start) throw new Error('JSON array not found');
  data = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  throw new Error('Candidate list could not be parsed. Model response: ' + raw.slice(0, 1200));
}
if (!Array.isArray(data)) throw new Error('Candidate response is not an array.');
const wanted = Math.max(1, Math.min(20, parseInt($('Workflow Config').first().json.company_count || '5', 10)));
const blocked = /(^|\.)(linkedin|xing|facebook|instagram|twitter|x|youtube|wikipedia|northdata|kompass|europages|wlw|firmenwissen|dnb|google|bing|yelp|gelbeseiten|11880|trustpilot|glassdoor|kununu|crunchbase|zoominfo|handelsregister|unternehmensregister|creditreform|opencorporates|bloomberg|reuters)\.[a-z.]+$/i;
const seen = new Set();
const out = [];
const skipped = [];
for (const c of data) {
  const rawUrl = String(c.company_url || '').trim();
  const mm = rawUrl.match(/^(https?):\/\/([^\/?#\s]+)/i);
  if (!mm) { skipped.push(rawUrl || '(empty)'); continue; }
  const host = mm[2].toLowerCase().replace(/:\d+$/, '');
  if (blocked.test(host) || !host.includes('.')) { skipped.push(host); continue; }
  const key = host.replace(/^www\./, '');
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({
    company_index: out.length + 1,
    discovered_name: String(c.company_name || 'Unknown').trim(),
    company_url: mm[1].toLowerCase() + '://' + host,
    city: String(c.city || '').trim(),
    automation_fit_reason: String(c.automation_fit_reason || '').trim()
  });
  if (out.length >= Math.min(25, wanted + 5)) break;
}
if (!out.length) throw new Error('No valid official website candidates were returned. Skipped: ' + skipped.join(' | '));
return out.map(x => ({ json: { ...x, total_companies: wanted, candidates_total: out.length }, pairedItem: { item: 0 } }));

const loop = $('Loop Over Items').first().json;
const home = String($input.first().json.data || '');
const parse = (str) => {
  const m = String(str || '').trim().match(/^(https?):\/\/([^\/?#\s]+)([^?#\s]*)/i);
  return m ? { origin: m[1].toLowerCase() + '://' + m[2].toLowerCase(), host: m[2].toLowerCase(), path: m[3] || '' } : null;
};
const finalMatch = home.match(/Final URL:\s*(https?:\/\/[^\s\n]+)/i);
const base = parse(finalMatch ? finalMatch[1] : loop.company_url) || parse(loop.company_url);
if (!base) return [];
const host = base.host.replace(/^www\./,'');
const origin = base.origin;
const baseClean = (origin + base.path).replace(/\/$/,'');
const re = /\[([^\]]*)\]\(([^\s)]+)\)/gi;
const found = new Map();
let m;
while ((m = re.exec(home)) !== null) {
  const label = String(m[1] || '').toLowerCase();
  let target; try { target = new URL(m[2], baseClean + '/').href; } catch (e) { continue; }
  if (!/^https?:/i.test(target)) continue;
  const u = parse(target);
  if (!u) continue;
  const h = u.host.replace(/^www\./,'');
  if (!(h === host || h.endsWith('.' + host))) continue;
  const path = u.path.toLowerCase();
  if (/\.(svg|png|jpe?g|gif|webp|pdf|css|js|zip)$/i.test(path)) continue;
  if (/board|sustainability|compliance|publications|cybersecurity|stories|innovations|career|jobs/.test(path)) continue;
  let score = 0;
  const t = label + ' ' + path;
  if (/impressum|imprint|legal-notice|corporate-information/.test(t)) score = 10;
  else if (/kontakt|contact|get-in-touch|ansprechpartner/.test(t)) score = 9;
  else if (/standort|locations|offices|headquarters/.test(t)) score = 8;
  else if (/about|ueber-uns|über-uns/.test(t)) score = 6;
  if (!score) continue;
  const clean = (u.origin + u.path).replace(/\/$/,'');
  if (clean === baseClean) continue;
  found.set(clean,Math.max(score,found.get(clean)||0));
}
const fallbacks = ['/impressum','/imprint','/kontakt','/contact','/legal-notice','/impressum.html','/kontakt.html'];
for (const p of fallbacks) {
  const u = origin + p;
  if (!found.has(u)) found.set(u,2);
}
const urls = [...found.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6).map(x=>x[0]);
return urls.map((url)=>({json:{url,company_url:loop.company_url},pairedItem:{item:0}}));

const loop = $('Loop Over Items').first().json;
const homeFull = String(($('Scrape Homepage').first().json || {}).data || '');
const home = homeFull.length > 12000 ? homeFull.slice(0, 7000) + '\n[...]\n' + homeFull.slice(-5000) : homeFull;
const pages = $input.all();
let extra = '', all = homeFull;
for (const it of pages) {
  const txt = String(it.json?.data || '');
  if (!txt || it.json?.error || txt.length < 150) continue;
  const h = txt.slice(0, 500).toLowerCase();
  if (/title:\s*404|404\s*-\s*page not found|seite nicht gefunden|page cannot be found|not found/.test(h)) continue;
  all += '\n' + txt;
  extra += '\n\n--- CONTACT / LEGAL SUBPAGE ---\n' + txt.slice(0, 6000);
}
let host = '';
try { host = new URL(loop.company_url).hostname.replace(/^www\./, '').toLowerCase(); } catch (e) {}
const deob = s => s
  .replace(/%40/g, '@').replace(/&#0*64;|&commat;|\\u0040/gi, '@')
  .replace(/\s*[\[\(\{]\s*(?:at|ät)\s*[\]\)\}]\s*/gi, '@')
  .replace(/\s*[\[\(\{]\s*(?:dot|punkt)\s*[\]\)\}]\s*/gi, '.');
const text = deob(all);
const re = /[A-Za-z0-9._%+\-]+@[A-Za-z0-9\-]+(?:\.[A-Za-z0-9\-]+)*\.[A-Za-z]{2,}/g;
const bad = /\.(png|jpe?g|gif|svg|webp|css|js|woff2?)$|sentry|example\.|domain\.|wixpress|yourname|beispiel|mustermann|name@/i;
const good = /^(info|kontakt|contact|office|mail|hello|hallo|vertrieb|sales|anfrage|service|zentrale)@/i;
const meh = /^(datenschutz|privacy|dpo|abuse|webmaster|presse|press|jobs|karriere|bewerbung|career|hr|noreply|no-reply)@/i;
const score = {};
for (const m of text.match(re) || []) {
  const e = m.replace(/[.\-_]+$/, '').toLowerCase();
  if (bad.test(e)) continue;
  const d = e.split('@')[1];
  let s = 1;
  if (host && (d === host || d.endsWith('.' + host) || host.endsWith('.' + d))) s += 5;
  if (good.test(e)) s += 3;
  if (meh.test(e)) s -= 3;
  score[e] = Math.max(score[e] || -99, s);
}
const candidate_emails = Object.entries(score).sort((a, b) => b[1] - a[1]).map(x => x[0]).slice(0, 5);
const email_obfuscated = /\[email[\s\u00a0]*protected\]/i.test(all);
const phones = [];
const pr = /(?:Tel(?:efon)?\.?|Phone|Fon|Telefon)\s*[:.]?\s*(\+?\d[\d\s()\/\-.]{6,22}\d)/gi;
let pm;
while ((pm = pr.exec(all)) !== null) { const p = pm[1].trim(); if (!phones.includes(p)) phones.push(p); if (phones.length >= 3) break; }
let contact_urls = [];
try { contact_urls = $('Find Contact & Impressum Links').all().map(i => i.json.url); } catch (e) {}
return [{ json: {
  company_index: loop.company_index, total_companies: loop.total_companies,
  discovered_name: loop.discovered_name, company_url: loop.company_url,
  automation_fit_reason: loop.automation_fit_reason,
  scrape_status: homeFull ? 'homepage_fetched' : 'homepage_empty_or_failed',
  candidate_emails, candidate_phones: phones, email_obfuscated, contact_urls,
  combined_content: ('--- HOMEPAGE ---\n' + home + extra).slice(0, 36000)
}, pairedItem: { item: 0 } }];

const input = $input.first().json || {};
const loop = $('Loop Over Items').first().json;
const comb = $('Combine Company Pages').first().json || {};
const cands = (comb.candidate_emails || []).map(x => String(x).toLowerCase());
const raw = String(input.text || '');
let obj = null;
try {
  const cleaned = raw.replace(/```(?:json)?/gi, '').trim();
  const a = cleaned.indexOf('{'), b = cleaned.lastIndexOf('}');
  if (a >= 0 && b > a) obj = JSON.parse(cleaned.slice(a, b + 1));
} catch {}
if (!obj) {
  obj = {
    company_name: loop.discovered_name || 'Unknown', phone: 'Not found', email: 'Not found', address: 'Not found',
    core_services: 'Not verified', clean_summary: 'AI analysis failed; manual review required', target_personas: [],
    automation_opportunities: 'Analysis unavailable. Review website manually.',
    subject_A: 'Automatisierungspotenziale bei ' + (loop.discovered_name || 'Ihrem Unternehmen'),
    body_A: 'Sehr geehrte Damen und Herren,\n\nwir haben Ihre Website betrachtet und möchten unverbindlich prüfen, ob sich einzelne wiederkehrende Abläufe in Ihrem Unternehmen sinnvoll automatisieren lassen.\n\nWäre ein kurzer Austausch dazu für Sie interessant?\n\nViele Grüße\nIhr Team von Example GmbH',
    subject_B: 'Kurze Frage zur Automatisierung',
    body_B: 'Sehr geehrte Damen und Herren,\n\nwäre ein kurzer Austausch zu möglichen Automatisierungen Ihrer Abläufe interessant?\n\nViele Grüße\nIhr Team von Example GmbH',
    evidence_note: 'Model output missing or invalid; fallback draft created.'
  };
}
const stripOpen = s => { let t = String(s || '').replace(/\r\n?/g, '\n').trim(); const mo = t.match(/^(?:Sehr geehrte|Guten Tag|Hallo|Liebe)[^\n,]*[,!]?\s*/i); if (mo) { t = t.slice(mo[0].length); t = t.charAt(0).toUpperCase() + t.slice(1); } return t; };
const stripClose = s => stripOpen(String(s || '')).replace(/\n+\s*(?:Mit freundlichen|Mit besten|Beste|Viele|Freundliche|Herzliche|Schöne)\s+Gr(?:ü|ue)(?:ß|ss)e?n?[\s\S]*$/i, '').replace(/\[Ihr Name\]/gi, '').trim();
const isMail = v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(v || '').trim());
let email = 'Not found';
const llm = String(obj.email || '').trim().toLowerCase();
if (isMail(llm) && cands.includes(llm)) email = llm;
else if (cands.length) email = cands[0];
const personas = Array.isArray(obj.target_personas) ? obj.target_personas.join(', ') : String(obj.target_personas || '');
let note = String(obj.evidence_note || '');
if (loop.site_note) note += ' | ' + loop.site_note;
if (comb.email_obfuscated) note += ' | Email is probably obfuscated (Cloudflare) - check Impressum manually.';
if ((comb.contact_urls || []).length) note += ' | Checked: ' + comb.contact_urls.join(', ');
return [{ json: {
  company_index: loop.company_index, total_companies: loop.total_companies,
  discovered_name: loop.discovered_name, company_url: loop.company_url,
  company_name: String(obj.company_name || loop.discovered_name || 'Unknown'),
  phone: String(obj.phone && obj.phone !== 'Not found' ? obj.phone : ((comb.candidate_phones || [])[0] || 'Not found')),
  email, email_candidates: cands.join(', '),
  address: String(obj.address || 'Not found'), core_services: String(obj.core_services || 'Not found'),
  summary: String(obj.clean_summary || 'Not found'), target_personas: personas,
  automation_opportunities: String(obj.automation_opportunities || 'Not available').replace(/\\n/g, '\n'),
  subject_A: String(obj.subject_A || 'Automatisierungspotenziale'), body_A: stripClose(obj.body_A),
  subject_B: String(obj.subject_B || 'Kurze Frage zur Automatisierung'), body_B: stripClose(obj.body_B),
  evidence_note: note.trim(),
  ai_parse_status: raw ? (input.error ? 'model_error_fallback' : 'parsed_or_fallback') : 'empty_model_output'
}, pairedItem: { item: 0 } }];

