const response = $input.first().json || {};
const form = response.data && typeof response.data === 'object' ? response.data : response;
const original = $('Validate AI Output').first().json;
const cfg = $('Workflow Config').first().json || {};
const g = (...keys) => { for (const k of keys) { if (form[k] !== undefined) return form[k]; } return undefined; };
const rawAction = g('Aktion', 'Action');
const hasForm = rawAction !== undefined;
const pick = (edited, fallback) => {
  const v = edited === undefined || edited === null ? '' : String(edited).trim();
  return v ? v : fallback;
};
const stripOpen = s => { let t = String(s || '').replace(/\r\n?/g, '\n').trim(); const mo = t.match(/^(?:(?:Sehr geehrte[rn]?|Guten Tag|Hallo|Liebe[rn]?|Dear|Hello|Hi|Bonjour|Madame|Monsieur|Estimad[oa]s?|Gentil[ei]|Beste|Geachte)\b|尊敬的)[^\n,:：]*[,:：!]?\s*/i); if (mo) { t = t.slice(mo[0].length); t = t.charAt(0).toUpperCase() + t.slice(1); } return t; };
const strip = s => stripOpen(s).replace(/\n+\s*(?:Mit freundlichen|Mit besten|Beste Gr|Viele Gr|Freundliche Gr|Herzliche Gr|Schöne Gr|Kind regards|Best regards|Sincerely|Cordialement|Bien cordialement|Cordiali saluti|Un cordial saludo|Atentamente|Met vriendelijke groet|此致)[\s\S]*$/i, '').replace(/\[Ihr Name\]/gi, '').trim();
const DE = { s: 'Sehr geehrte Damen und Herren,', c: 'Mit freundlichen Grüßen', o: 'Sollten Sie keine weiteren Nachrichten von uns wünschen, antworten Sie bitte kurz mit „Abmelden“. Wir nehmen Sie dann umgehend aus unserem Verteiler.' };
const EN = 'If you do not wish to receive further messages from us, simply reply with “Unsubscribe” and we will remove you from our list immediately.';
const L = {
  'Deutschland': DE,
  'Österreich': DE,
  'Schweiz': { s: 'Sehr geehrte Damen und Herren', c: 'Freundliche Grüsse', o: 'Sollten Sie keine weiteren Nachrichten von uns wünschen, antworten Sie bitte kurz mit „Abmelden“. Wir nehmen Sie dann umgehend aus unserem Verteiler.' },
  'Niederlande': { s: 'Geachte heer/mevrouw,', c: 'Met vriendelijke groet,', o: 'Wilt u geen verdere berichten van ons ontvangen? Antwoord dan kort met “Afmelden”; wij verwijderen u dan direct uit onze lijst.' },
  'Frankreich': { s: 'Madame, Monsieur,', c: 'Cordialement,', o: 'Si vous ne souhaitez plus recevoir de messages de notre part, répondez simplement « Désinscription » : nous vous retirerons aussitôt de notre liste.' },
  'Italien': { s: 'Gentili Signore e Signori,', c: 'Cordiali saluti,', o: 'Se non desidera ricevere ulteriori messaggi da parte nostra, risponda semplicemente con «Annulla iscrizione»: la rimuoveremo subito dal nostro elenco.' },
  'Spanien': { s: 'Estimados señores:', c: 'Un cordial saludo,', o: 'Si no desea recibir más mensajes nuestros, responda simplemente con «Baja»; le eliminaremos de inmediato de nuestra lista.' },
  'Großbritannien': { s: 'Dear Sir or Madam,', c: 'Kind regards,', o: EN },
  'USA': { s: 'Dear Sir or Madam,', c: 'Best regards,', o: EN },
  'China': { s: '尊敬的负责人：', c: '此致敬礼', o: '如您不希望再收到我们的邮件，请回复“退订”，我们将立即把您从名单中删除。' }
};
const T = L[String(cfg.country || 'Deutschland').trim()] || DE;
const email = pick(g('E-Mail', 'email'), original.email);
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) && email !== 'Not found';
const version = /B\s*$/.test(String(g('E-Mail-Version', 'Email Version') || '').trim().toUpperCase()) ? 'B' : 'A';
const subjectA = pick(g('Betreff A', 'Subject A'), original.subject_A);
const subjectB = pick(g('Betreff B', 'Subject B'), original.subject_B);
const bodyA = strip(pick(g('Text A', 'Body A'), original.body_A));
const bodyB = strip(pick(g('Text B', 'Body B'), original.body_B));
const subject = version === 'B' ? subjectB : subjectA;
const body = version === 'B' ? bodyB : bodyA;
const extraRaw = g('Zusatztext', 'Extra Text');
const extra = hasForm && extraRaw !== undefined ? String(extraRaw || '').trim() : String(cfg.email_extra_text || '').trim();
const company = String(cfg.sender_company || 'Example GmbH').trim();
const impressum = String(cfg.email_impressum || '').trim();
const signature = T.c + '\n\n' + company;
const finalBody = [T.s, body, extra, signature, T.o, impressum].filter(Boolean).join('\n\n');
let action = 'Skip / Cancel';
if (!hasForm) action = 'Save to Supabase Only';
else if (/senden|send/i.test(String(rawAction))) action = 'Approve & Send Email';
else if (/speichern|save/i.test(String(rawAction))) action = 'Save to Supabase Only';
return [{json:{
 ...original,
 action,
 company_name: pick(g('Firmenname', 'company_name'), original.company_name),
 email,
 email_valid: emailValid,
 phone: pick(g('Telefon', 'phone'), original.phone),
 address: pick(g('Adresse', 'address'), original.address),
 summary: pick(g('Zusammenfassung', 'summary'), original.summary),
 email_version: version,
 subject_a: subjectA, subject_b: subjectB, body_a: bodyA, body_b: bodyB,
 subject,
 email_body: body,
 extra_text: extra,
 final_body: finalBody
},pairedItem:{item:0}}];

const x = $('Apply Review Edits').first().json;
const ex = $input.first().json || {};
const nn = (v) => {
  const s = (v === undefined || v === null) ? '' : String(v).trim();
