const f = $('Workflow Config').first().json;
const region = $('Select Region (Step 2)').first().json.Region || 'Alle';
const wanted = Math.max(1, Math.min(20, parseInt(f.company_count || '5', 10)));
const ask = Math.min(25, wanted + 5);
const focus = String(f.custom_focus || '').trim() || 'None';
const system = 'You are a precise B2B market researcher. If you have a web search tool, use it. Respond with ONLY a valid JSON array. No markdown, no explanations, no reasoning text before or after the array.';
const prompt = `Find REAL, currently existing B2B companies (use web search if you have it).
Criteria:
- Industry: ${f.industry}
- Country: ${f.country}
- Region: ${region}
- Additional focus: ${focus}

Rules:
- Return ${ask} different companies. Search with several queries (German and English) before answering.
- Prefer mid-sized companies / Mittelstand (about 20-500 employees) that publish an Impressum or contact page with a direct email. Avoid DAX / Fortune-500 corporations and subsidiaries of them.
