  const m = String(it.json.company_url || '').match(/^https?:\/\/([^\/?#\s]+)/i);
  if (!m) continue;
  const h = m[1].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '');
  if (/^[a-z0-9.-]+$/.test(h)) hosts.add(h);
}
const list = [...hosts].map(q).join(',') || "''";
const query = `SELECT host, 'already saved' AS source FROM (SELECT lower(regexp_replace(regexp_replace(company_url,'^https?://(www[.])?',''),'[/?#:].*','')) AS host FROM public.leads WHERE company_url IS NOT NULL) t WHERE host IN (${list}) UNION ALL SELECT domain AS host, 'rejected earlier' AS source FROM public.rejected_sites WHERE domain IN (${list}) AND industry = ${q(industry)}`;
return [{ json: { query, hosts: [...hosts] } }];

const cands = $('Validate & Normalize Candidates').all().map(i => i.json);
const known = new Map();
for (const it of $input.all()) {
  const h = String((it.json || {}).host || '').toLowerCase();
  if (h) known.set(h, (it.json || {}).source || 'known');
}
const keep = [], dropped = [];
for (const c of cands) {
  const host = String(c.company_url).replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#:]/)[0].toLowerCase();
  if (known.has(host)) dropped.push(host + ' (' + known.get(host) + ')'); else keep.push(c);
}
if (!keep.length) throw new Error('All candidates are already known: ' + dropped.join(', ') + '. Run again or change region/focus.');
return keep.map((c, i) => ({ json: { ...c, company_index: i + 1, candidates_total: keep.length, dedupe_dropped: dropped.length }, pairedItem: { item: 0 } }));

